// ── 시도/시군구 파생 ──
function guSlug(sidoSlug, region){
  // region.slug = sido-gu-dong  → sido-gu
  const parts = region.slug.split("-");
  return parts.slice(0,2).join("-");
}
const SIDO_MAP = Object.fromEntries(SIDO_LIST.map(s=>[s.slug,s]));
const GU_MAP = {};      // guSlug -> {slug, sido(obj), sigungu(name)}
const GU_OF_SIDO = {};  // sidoSlug -> [guSlug...]
const DONGS_OF_GU = {}; // guSlug -> [region...]
for (const r of regions){
  const sd = SIDO_LIST.find(s => r.slug.startsWith(s.slug + "-"));
  if (!sd) continue;
  const gs = guSlug(sd.slug, r);
  if (!GU_MAP[gs]){
    GU_MAP[gs] = { slug:gs, sido:sd, sigungu:r.sigungu };
    (GU_OF_SIDO[sd.slug] ||= []).push(gs);
    DONGS_OF_GU[gs] = [];
  }
  DONGS_OF_GU[gs].push(r);
}

// ── 시(구를 가진 시) 레벨 파생 ──
const CITY_MAP = {};       // citySlug -> {slug, sido(obj), city(시이름), gus:[guSlug...]}
const CITY_OF_SIDO = {};   // sidoSlug -> [citySlug...]
const GU_TO_CITY = {};     // guSlug -> citySlug
function lcp(arr){ if(!arr.length) return ""; let p=arr[0]; for(const s of arr){ let i=0; while(i<p.length&&i<s.length&&p[i]===s[i])i++; p=p.slice(0,i);} return p; }
{
  const byCity={}; // (sido.slug|시이름) -> {sido, city, gus:[]}
  for(const gs in GU_MAP){
    const g=GU_MAP[gs];
    if(!/시 .*구$/.test(g.sigungu)) continue;   // "○○시 ○구" 형태만
    const city=g.sigungu.split(" ")[0];
    const key=g.sido.slug+"|"+city;
    (byCity[key] ||= {sido:g.sido, city, gus:[]}).gus.push(gs);
  }
  for(const key in byCity){
    const c=byCity[key];
    if(c.gus.length<1) continue;
    let cs=lcp(c.gus);
    const cut=cs.lastIndexOf("si");           // 'si'로 끝나도록 보정
    if(cut>0) cs=cs.slice(0,cut+2);
    if(!cs||CITY_MAP[cs]||SIDO_MAP[cs]) continue;
    CITY_MAP[cs]={slug:cs, sido:c.sido, city:c.city, gus:c.gus};
    (CITY_OF_SIDO[c.sido.slug] ||= []).push(cs);
    for(const gs of c.gus) GU_TO_CITY[gs]=cs;
  }
}

function esc(s){ return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[m])); }

/* ===================== 본문 생성 엔진 (4,000자급) ===================== */
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function rng(seed){let a=seed>>>0;return function(){a|=0;a=(a+0x6d2b79f5)|0;let t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function pick(arr,r){return arr[Math.floor(r()*arr.length)];}
function pick2(arr,r){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return [a[0],a[1]];}
function pick3(arr,r){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return [a[0],a[1],a[2]];}
function pickN(arr,n,r){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a.slice(0,n);}
function P(s){return `<p>${s}</p>`;}
function H(s){return `<h2>${s}</h2>`;}

// 발행일/수정일 (수정일=오늘~13일 전, 발행일=수정일에서 두세 달 전) — slug 시드로 고정
function pageDates(seedStr){
  const seed = hash(seedStr);
  const now = Date.now(); const day = 86400000;
  const modAgo = seed % 14;                 // 0~13일 전
  const pubAgo = modAgo + 60 + (seed % 240); // 두세 달 더 전
  const mod = new Date(now - modAgo*day);
  const pub = new Date(now - pubAgo*day);
  const f = d => `${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,"0")}.${String(d.getDate()).padStart(2,"0")}`;
  const iso = d => d.toISOString();
  return { pubT:f(pub), modT:f(mod), pubISO:iso(pub), modISO:iso(mod) };
}
function dateMeta(d){
  return `<div class="datemeta"><span>📅 발행 <b>${d.pubT}</b></span><span>🔄 수정 <b>${d.modT}</b></span></div>`;
}
