// 시도 × 과목
function pageSidoSubject(sd, s){
  const r = rng(hash(sd.slug+"|"+s.slug));
  const C = commonPools(sd.name, s.name);
  let art = dateMeta(pageDates(sd.slug+"|"+s.slug));
  art += vSummary(`${sd.name} ${s.name} 과외, 어떻게 시작하나요?`, `${sd.name}에서 방문·화상 1:1 ${s.name} 과외를 무료 상담으로 시작할 수 있습니다. 검증된 ${s.name} 선생님을 학생 수준에 맞춰 매칭합니다.`);
  art += H(`📘 ${sd.name} ${s.name} 과외, 세상의모든과외에서`)+P(pick(C.intro,r));
  art += H(`🎯 왜 ${sd.name}에서 1:1 ${s.name} 과외일까요`)+P(pick(C.why1,r))+P(pick(C.why2,r));
  art += vICards([{e:"🏠",b:"방문 · 화상 모두",s:"상황에 맞게"},{e:"👤",b:"1:1 전담",s:"개별 맞춤"},{e:"🎓",b:"검증된 선생님",s:"학력·경력 확인"},{e:"🌍",b:"전국 매칭",s:"지역 제한 없음"}]);
  art += vCompare(["구분","학원·그룹","1:1 과외"],[[{t:"수업 집중"},{t:"여러 명",k:"x"},{t:"한 명 집중",k:"o"}],[{t:"진도"},{t:"평균",k:"x"},{t:"내 아이 속도",k:"o"}],[{t:"약점 보완"},{t:"놓치기 쉬움",k:"x"},{t:"콕 짚어",k:"o"}]]);
  art += H(`학원과 1:1 ${s.name} 과외 비교`)+P(pick2(C.compare,r).join(""));
  art += H(`${sd.name} ${s.name} 과외 비용`)+P(pick2(C.cost,r).join(""));
  art += H(`${sd.name} 학년별 ${s.name} 학습`)+P(pick(C.grade,r));
  const dpa = pick3(subjectDeep(s.slug, sd.name), r);
  art += H(`${sd.name} ${s.name}, 이렇게 공부합니다`)+P(dpa[0])+P(dpa[1])+P(dpa[2]);
  art += H(`방문 · 화상 ${s.name} 과외 모두`)+P(pick2(C.method,r).join(""))+P(pick(C.online,r));
  art += H(`이런 학생에게 잘 맞아요`)+P(pick(C.checklist,r));
  art += H(`🧠 ${sd.name} 학습 습관까지`)+P(pick(C.habit,r));
  art += H(`🏡 ${sd.name} 학습 환경`)+P(pick(C.env,r));
  art += H(`${sd.name} 학부모님께`)+P(pick2(C.parent,r).join(""));
  art += H(`${sd.name} ${s.name} 시험 대비`)+P(pick2(C.examPrep,r).join(""));
  art += H(`처음이어도 안심`)+P(pick(C.safety,r));
  art += H(`${sd.name} 맞춤이라는 것`)+P(pick(C.region,r));
  art += H(`검증된 ${s.name} 선생님 매칭`)+P(pick(C.trust,r));
  art += H(`🚀 ${sd.name} ${s.name} 수업은 이렇게`)+P(pick2(C.process,r).join(""));
  art += vSteps([{t:"무료 상담",d:"학년·과목·목표"},{t:"선생님 매칭",d:`${sd.name} 맞춤 연결`},{t:"첫 수업·진단",d:"시작점 결정"},{t:"정규 수업",d:"방문·화상 1:1"}]);
  art += H(`이런 변화를 기대할 수 있어요`)+P(pick2(C.result,r).join(""));
  art += H(`방문과 화상, 어떻게 고를까요`)+P(pick(C.guide,r));
  art += H(`${sd.name} ${s.name} 과외 신청`)+P(pick(C.how,r))+P(pick(C.closing,r));
  art += P(`세상의모든과외는 ${J(sd.name,"을","를")} 비롯한 전국에서 학생과 ${s.name} 선생님을 잇는 일을 합니다. 학원과 달리 정해진 틀에 학생을 맞추는 것이 아니라, 학생에게 수업을 맞춥니다. ${sd.name}에서 ${s.name} 과외를 알아보고 계신다면 지금 무료 상담을 남겨 주세요. 맞는 선생님을 찾는 일은 한 번의 상담에서 시작됩니다.`);
  const faqs = faqsFor(sd.name, s.name);
  art += faqBlock(faqs);
  const gus = (GU_OF_SIDO[sd.slug]||[]).map(gs=>GU_MAP[gs]);
  const ld = areaLd(sd.full, `${ORIGIN}/${sd.slug}/${s.slug}`,
    [{name:"홈",item:ORIGIN+"/"},{name:sd.name,item:`${ORIGIN}/${sd.slug}`},{name:`${s.name} 과외`,item:`${ORIGIN}/${sd.slug}/${s.slug}`}]);
  ld.push({"@context":"https://schema.org","@type":"FAQPage","mainEntity":faqs.map(f=>({"@type":"Question","name":f.q,"acceptedAnswer":{"@type":"Answer","text":f.a}}))});
  const body=`
<div class="wrap"><div class="bc"><a href="/">홈</a> › <a href="/${sd.slug}">${esc(sd.name)}</a> › ${esc(s.name)}</div></div>
<section class="sec" style="padding-top:16px"><div class="wrap">
${thumb(null, esc(sd.name)+" "+esc(s.name), esc(sd.name)+" "+esc(s.name)+" 과외", s.color)}
<article class="article">${art}
<div class="trial"><b>${esc(sd.name)} ${esc(s.name)} 과외 무료 상담</b><span>지금 신청하면 맞는 선생님을 빠르게 연결해 드립니다.</span><button class="btn" onclick="fillForm('${esc(sd.name)}','${esc(s.name)}')">상담 신청하기 →</button></div></article>
<div class="bodycol"><h2 style="margin-top:32px;font-size:18px;text-align:left">${esc(sd.name)} 시·군·구 ${esc(s.name)} 과외</h2>
<div class="chips">${sidoChildren(sd).map(c=>`<a href="/${c.slug}/${s.slug}">${esc(c.label)}</a>`).join("")}</div></div></div></section>`;
  return layout({title:`${sd.name} ${s.name} 과외 · 방문·화상 1:1 | ${SITE_NAME}`,desc:`${sd.name} ${s.name} 과외. 방문·화상 1:1로 검증된 ${s.name} 선생님 매칭. ${sd.full} ${s.name} 과외 무료 상담.`,canonical:`${ORIGIN}/${sd.slug}/${s.slug}`,body,ld});
}

