  art += H(`🚀 ${g.sigungu} ${s.name} 수업은 이렇게`)+P(pick2(C.process,r).join(""));
  art += vSteps([{t:"무료 상담",d:"학년·과목·목표"},{t:"선생님 매칭",d:`${g.sigungu} 맞춤 연결`},{t:"첫 수업·진단",d:"시작점 결정"},{t:"정규 수업",d:"방문·화상 1:1"}]);
  art += H(`이런 변화를 기대할 수 있어요`)+P(pick2(C.result,r).join(""));
