const INDEXNOW_KEY_SEMOGWA="41990cbcc27241c6b899d18d983370a3";
async function indexnowPing(u){
  const all=allUrls();
  const start=Math.max(0,parseInt((u&&u.searchParams.get("start"))||"0")||0);
  const n=Math.min(10000,Math.max(1,parseInt((u&&u.searchParams.get("n"))||"1000")||1000));
  const urls=all.slice(start,start+n);
  if(!urls.length) return new Response(`제출할 URL 없음 (전체 ${all.length}개, start=${start})`,{headers:{"content-type":"text/plain; charset=utf-8"}});
  const payload={ host:new URL(ORIGIN).host, key:INDEXNOW_KEY_SEMOGWA, keyLocation:`${ORIGIN}/${INDEXNOW_KEY_SEMOGWA}.txt`, urlList:urls };
  try{
    const resp=await indexnowFetch({ method:"POST", headers:{"Content-Type":"application/json; charset=utf-8"}, body:JSON.stringify(payload) });
    const next=start+urls.length;
    return new Response(`IndexNow 제출 완료\n범위: ${start} ~ ${next-1}\n제출 URL 수: ${urls.length}\n전체 URL 수: ${all.length}\n응답 코드: ${resp.status}\n다음: ${ORIGIN}/indexnow-ping?start=${next}&n=${n}`,{headers:{"content-type":"text/plain; charset=utf-8"}});
  }catch(e){ return new Response(`IndexNow 제출 실패: ${e.message}`,{status:500,headers:{"content-type":"text/plain; charset=utf-8"}}); }
}
/* 기존 RSS 를 Atom 으로 변환한다 (피드 항목 로직을 중복 구현하지 않기 위함) */
function atomFromRss(xml, selfUrl){
  const one=function(s,t){ const m=s.match(new RegExp("<"+t+"(?:\\s[^>]*)?>([\\s\\S]*?)<\\/"+t+">")); return m?m[1]:""; };
  const head=xml.split("<item>")[0];
  const chTitle=one(head,"title"), chLink=one(head,"link"), chDesc=one(head,"description");
  const items=xml.match(/<item>[\s\S]*?<\/item>/g)||[];
  const now=new Date().toISOString();
  let x='<?xml version="1.0" encoding="UTF-8"?><feed xmlns="http://www.w3.org/2005/Atom" xml:lang="ko">';
  x+="<title>"+chTitle+"</title>";
  if(chDesc) x+="<subtitle>"+chDesc+"</subtitle>";
  x+='<link href="'+chLink+'"/><link rel="self" href="'+selfUrl+'"/>';
  x+="<id>"+(chLink||selfUrl)+"</id><updated>"+now+"</updated>";
  for(const it of items){
    const t=one(it,"title"), l=one(it,"link")||one(it,"guid"), d=one(it,"description"), pd=one(it,"pubDate");
    let up=now; if(pd){ const dt=new Date(pd); if(!isNaN(dt.getTime())) up=dt.toISOString(); }
    x+="<entry><title>"+t+"</title>";
    x+='<link href="'+l+'"/><id>'+l+"</id><updated>"+up+"</updated>";
    if(d) x+="<summary>"+d+"</summary>";
    x+="</entry>";
  }
  return x+"</feed>";
}
function rssFeed(){
  const base=[];
  for(const sd of SIDO_LIST) base.push({u:`/${sd.slug}`,t:`${sd.name} 1:1 과외`});
  for(const cs in CITY_MAP) base.push({u:`/${cs}`,t:`${CITY_MAP[cs].city} 1:1 과외`});
  for(const gs in GU_MAP) base.push({u:`/${gs}`,t:`${GU_MAP[gs].sigungu} 1:1 과외`});
  for(const r of regions) base.push({u:`/${r.slug}`,t:`${shortName(r.name)} 1:1 과외`});
  for(const r of regions){ for(const s of SUBJECTS) base.push({u:`/${r.slug}/${s.slug}`,t:`${shortName(r.name)} ${s.name} 과외`}); }
  for(const gs in GU_MAP){ for(const s of SUBJECTS) base.push({u:`/${gs}/${s.slug}`,t:`${GU_MAP[gs].sigungu} ${s.name} 과외`}); }
  /* 최근 항목 위주로 매일 회전. 1,000개는 사실상 전체라 피드 구실을 못 해 100개로 줄였다 */
  const ranked=base.map(it=>{ const m=rssRankDate(ORIGIN+it.u); return {u:it.u,t:it.t,m:m,ts:m.getTime()}; })
    .sort((a,b)=>b.ts-a.ts).slice(0,100);
  const items=ranked.map(it=>{
    return `<item><title>${esc(it.t)}</title><link>${ORIGIN}${it.u}</link><guid>${ORIGIN}${it.u}</guid><pubDate>${it.m.toUTCString()}</pubDate><description>${esc(it.t)} · 방문·화상 1:1 과외 매칭. 국어·영어·수학·사회·과학.</description></item>`;
  }).join("");
  return `<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0"><channel><title>${SITE_NAME}</title><link>${ORIGIN}</link><description>전국 방문·화상 1:1 과외 매칭 · 국어·영어·수학·사회·과학</description><language>ko</language>${items}</channel></rss>`;
}
